  await openManage(page, { divisions: [], tab: 'livestream' });

  const overlay = page.getByTestId('manage-wide-overlay');
  const content = overlay.getByTestId('manage-wide-content');
  await expect(overlay).toBeVisible();
  await expect(overlay.getByTestId('manage-wide-operation-tabs').locator('button')).toHaveCount(4);
  await expect(overlay.getByTestId('manage-wide-tab-livestream')).toHaveAttribute('aria-current', 'page');
  await expect(content.getByRole('heading', { name: 'Trực tiếp', exact: true })).toHaveCount(0);
  await expect(content.getByText('BTC tạo camera và gán camera vào trận.', { exact: false })).toHaveCount(0);
  await expect(content.getByRole('heading', { name: 'Camera của giải', exact: true })).toBeVisible();
  await expect(overlay.getByTestId('manage-wide-empty')).toHaveCount(0);
  await expect(overlay.getByTestId('manage-wide-division-selector')).toHaveCount(0);
  await expect.poll(() => new URL(page.url()).searchParams.get('tab')).toBe('livestream');

  const addCamera = content.getByRole('button', { name: 'Thêm camera' });
  await expect(addCamera).toBeVisible();
  await expect(page.getByRole('dialog', { name: 'Thêm camera' })).toHaveCount(0);
  await addCamera.click();

  const dialog = page.getByRole('dialog', { name: 'Thêm camera' });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole('heading', { name: 'Thêm camera' })).toBeVisible();
  await expect(dialog.getByLabel('Tên camera')).toBeVisible();
  await expect(dialog.getByLabel('Sân dùng camera này')).toBeVisible();
