  await expect(dialog.getByLabel('URL phát trực tiếp')).toBeVisible();
  await dialog.getByRole('button', { name: 'PUSH' }).click();
  await expect(dialog.getByLabel('URL phát trực tiếp')).toHaveCount(0);
});

test('shows PUSH publish details outside the dialog after camera creation', async ({ page }) => {
  await openManage(page, { divisions: [], tab: 'livestream' });

  const publish = {
    protocol: 'RTMP',
    streamName: 'synthetic-publish-key',
    url: 'rtmp://sporto.asia:1935/live/synthetic-publish-key',
    rtmpUrl: 'rtmp://sporto.asia:1935/live',
    srtUrl: 'srt://sporto.asia:8890?streamid=synthetic-publish-key',
  };
  const createdCamera = {
    id: 'synthetic-created-camera',
    tournamentId,
    name: 'Camera sân 1',
    mode: 'PUSH',
    courtId: null,
    protocol: 'RTMP',
    streamName: publish.streamName,
    status: 'IDLE',
    playbackUrl: null,
    createdAt: '2026-10-05T10:00:00.000Z',
    updatedAt: '2026-10-05T10:00:00.000Z',
    publish,
  };
  let created = false;
  await page.route(`**/api/v1/livestream/tournaments/${tournamentId}/cameras`, async (route) => {
    if (route.request().method() === 'POST') {
      expect(route.request().postDataJSON()).toEqual({
        name: 'Camera sân 1',
        mode: 'PUSH',
        protocol: 'RTMP',
      });
      created = true;
      await fulfillApi(route, { data: createdCamera });
      return;
    }

    await fulfillApi(route, { data: created ? [createdCamera] : [] });
  });

  await page.getByRole('button', { name: 'Thêm camera' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm camera' });
  await dialog.getByLabel('Tên camera').fill('Camera sân 1');
  await dialog.getByRole('button', { name: 'Tạo camera' }).click();

  await expect(page.getByRole('dialog', { name: 'Thêm camera' })).toHaveCount(0);
  await expect(page.getByText('Link publish vừa tạo')).toBeVisible();
  await expect(page.getByText(publish.url, { exact: true })).toBeVisible();
  await expect(page.getByText(publish.streamName, { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Sao chép Server URL' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Sao chép Stream Key' })).toBeVisible();
});

