import 'package:app_quanly_giaidau/domain/entities/tournament_registration.dart';
import 'package:app_quanly_giaidau/features/register/utils/division_selection.dart';
import 'package:flutter_test/flutter_test.dart';

TournamentDivisionOption _division(String id, {String? status}) =>
    TournamentDivisionOption(id: id, name: id, status: status);

void main() {
  group('registration division selection', () {
    test('keeps an explicitly selected active division', () {
      final divisions = [
        _division('active-a', status: 'ACTIVE'),
        _division('active-b', status: 'ACTIVE'),
      ];

      expect(
        resolveRegistrationDivisionId(
          divisions,
          preferredDivisionId: 'active-b',
        ),
        'active-b',
      );
    });

    test('auto-selects the only active division and ignores cancelled ones', () {
      final divisions = [
        _division('cancelled', status: 'CANCELLED'),
        _division('active', status: 'ACTIVE'),
      ];

      expect(resolveRegistrationDivisionId(divisions), 'active');
      expect(activeRegistrationDivisions(divisions), [divisions.last]);
    });

    test('requires explicit choice for multiple active divisions', () {
      final divisions = [
        _division('active-a', status: 'ACTIVE'),
        _division('active-b', status: 'ACTIVE'),
      ];

      expect(resolveRegistrationDivisionId(divisions), isNull);
    });

    test('does not choose a cancelled division', () {
      expect(
        resolveRegistrationDivisionId([
          _division('cancelled', status: 'CANCELLED'),
        ]),
        isNull,
      );
    });
  });
}

import 'package:app_quanly_giaidau/features/tournament/screens/quick_tournament_format_mapping.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  group('quick tournament flexible formats', () {
    test('offers flexible singles and doubles for racket sports only', () {
      final racketFormats = quickTournamentFormatOptions(isFootball: false);
      final footballFormats = quickTournamentFormatOptions(isFootball: true);

      expect(racketFormats, containsAll(['OPEN_SINGLES', 'OPEN_DOUBLES']));
      expect(footballFormats, isNot(contains('OPEN_SINGLES')));
      expect(footballFormats, isNot(contains('OPEN_DOUBLES')));
    });

    test('keeps the pre-existing first options as the defaults', () {
      expect(
        quickTournamentFormatOptions(isFootball: false).first,
        'MALE_SINGLES',
      );
      expect(
        quickTournamentFormatOptions(isFootball: true).first,
        'FOOTBALL_MALE',
      );
    });

    test('maps open singles to the singles API contract without gender fields', () {
      expect(quickTournamentApiFormatFields('OPEN_SINGLES'), {
        'format': 'singles',
      });
      expect(quickTournamentDivisionFormatFields('OPEN_SINGLES'), {
        'matchType': 'SINGLES',
      });
    });

    test('maps open doubles to the doubles API contract without gender fields', () {
      expect(quickTournamentApiFormatFields('OPEN_DOUBLES'), {
        'format': 'doubles',
      });
      expect(quickTournamentDivisionFormatFields('OPEN_DOUBLES'), {
        'matchType': 'DOUBLES',
      });
    });

    test('never sends OPEN or MIXED as a flexible division payload', () {
      for (final key in ['OPEN_SINGLES', 'OPEN_DOUBLES']) {
        final payload = {
          ...quickTournamentApiFormatFields(key),
          ...quickTournamentDivisionFormatFields(key),
        };
        expect(payload.containsKey('genderRestriction'), isFalse);
        expect(payload.values, isNot(contains('OPEN')));
        expect(payload.values, isNot(contains('MIXED_DOUBLES')));
      }
    });

    test('keeps the restricted racket formats on their previous contract', () {
      expect(quickTournamentApiFormatFields('MALE_SINGLES'), {
        'format': 'singles',
        'genderRestriction': 'MALE',
      });
      expect(quickTournamentApiFormatFields('FEMALE_SINGLES'), {
        'format': 'singles',
        'genderRestriction': 'FEMALE',
      });
      expect(quickTournamentApiFormatFields('MALE_DOUBLES'), {
        'format': 'doubles',
        'genderRestriction': 'MALE',
      });
      expect(quickTournamentApiFormatFields('FEMALE_DOUBLES'), {
        'format': 'doubles',
        'genderRestriction': 'FEMALE',
      });
      expect(quickTournamentApiFormatFields('MIXED_DOUBLES'), {
        'format': 'doubles',
        'genderRestriction': 'MIXED',
      });

      expect(quickTournamentDivisionFormatFields('MALE_SINGLES'), {
        'matchType': 'SINGLES',
        'genderRestriction': 'MALE',
      });
      expect(quickTournamentDivisionFormatFields('MIXED_DOUBLES'), {
        'matchType': 'MIXED_DOUBLES',
        'genderRestriction': 'MIXED',
      });
    });

    test('keeps the football formats on their previous contract', () {
      for (final entry in {
        'FOOTBALL_MALE': 'MALE',
        'FOOTBALL_FEMALE': 'FEMALE',
        'FOOTBALL_MIXED': 'MIXED',
      }.entries) {
        expect(quickTournamentApiFormatFields(entry.key), {
          'format': 'doubles',
          'genderRestriction': entry.value,
        });
        expect(quickTournamentDivisionFormatFields(entry.key), {
          'matchType': 'DOUBLES',
          'genderRestriction': entry.value,
        });
      }
    });
  });
}

import 'package:flutter_test/flutter_test.dart';
import 'package:app_quanly_giaidau/domain/entities/tournament_registration.dart';

void main() {
  group('TournamentDivisionOption capacity', () {
    test('reads fractional team slots from the server capacity projection', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Doubles A',
        'maxParticipants': 4,
        '_count': {'participants': 4},
        'capacity': {'occupiedTeamSlots': 0.5, 'maxTeamSlots': 4},
      });

      expect(division.occupiedTeamSlots, 0.5);
      expect(division.effectiveMaxTeamSlots, 4);
    });

    test('keeps half capacity while only four unpaired members registered', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Doubles A',
        '_count': {'participants': 4},
        'capacity': {'occupiedTeamSlots': 2.0, 'maxTeamSlots': 4},
      });

      expect(division.isFull, isFalse);
    });

    test('reports full only at four team slots', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Doubles A',
        'capacity': {'occupiedTeamSlots': 3.5, 'maxTeamSlots': 4},
      });
      final full = TournamentDivisionOption.fromJson({
        'id': 'division-2',
        'name': 'Doubles B',
        'capacity': {'occupiedTeamSlots': 4.0, 'maxTeamSlots': 4},
      });

      expect(division.isFull, isFalse);
      expect(full.isFull, isTrue);
    });

    test('does not report an uncapped division as full', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Open',
        'capacity': {'occupiedTeamSlots': 40.0, 'maxTeamSlots': null},
      });

      expect(division.isFull, isFalse);
    });

    test('falls back to participant row count for non-doubles formats', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Singles',
        'matchType': 'SINGLES',
        'maxParticipants': 4,
        '_count': {'participants': 3},
      });

      expect(division.occupiedTeamSlots, 3.0);
      expect(division.isFull, isFalse);
    });

    test('leaves doubles occupancy unknown instead of counting rows', () {
      // 4 hồ sơ ở nội dung đôi có thể chỉ là 2 suất, nên số bản ghi KHÔNG
      // được dùng làm sức chứa khi thiếu projection của server.
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Doubles A',
        'matchType': 'DOUBLES',
        'maxParticipants': 4,
        '_count': {'participants': 4},
      });

      expect(division.occupiedTeamSlots, isNull);
      expect(division.teamSlotsLabel, isNull);
      expect(division.isFull, isFalse);
    });

    test('leaves mixed doubles occupancy unknown too', () {
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Đôi Nam Nữ',
        'matchType': 'MIXED_DOUBLES',
        'maxParticipants': 4,
        '_count': {'participants': 4},
      });

      expect(division.occupiedTeamSlots, isNull);
      expect(division.isFull, isFalse);
    });

    test('leaves an unrecognised format unknown instead of counting rows', () {
      // matchType ngoài danh sách app biết (chưa có quy ước nào map về đôi/đơn)
      // thì 4 hồ sơ KHÔNG được đo thành 4 suất rồi báo đầy nhầm. Thiếu
      // projection của server thì sức chứa CHƯA BIẾT, không phải bằng số dòng.
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Four on four',
        'matchType': 'FOURS',
        'maxParticipants': 4,
        '_count': {'participants': 4},
      });

      expect(division.occupiedTeamSlots, isNull);
      expect(division.teamSlotsLabel, isNull);
      expect(division.isFull, isFalse);
    });

    test('leaves a missing match format unknown instead of counting rows', () {
      // Backend chưa gán matchType (nội dung tạo tay) — null KHÔNG phải là
      // "đơn", nên cũng không được phép suy ra sức chứa từ số bản ghi.
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
        'name': 'Chưa cấu hình',
        'maxParticipants': 4,
        '_count': {'participants': 4},
      });

      expect(division.occupiedTeamSlots, isNull);
      expect(division.teamSlotsLabel, isNull);
      expect(division.isFull, isFalse);
    });

    test('still shows the server projection for an unrecognised format', () {
      // Projection là nguồn chân lý bất kể format: nếu backend đã gửi thì
      // phải hiện đúng con số, không phải vì "không đọc được format" mà bỏ trống.
      final division = TournamentDivisionOption.fromJson({
        'id': 'division-1',
