const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');
const ts = require('typescript');

const repoRoot = path.resolve(__dirname, '../..');

// The catalog module imports `@/types/tournament`, which plain Node cannot
// resolve, so the real sources are transpiled and their imports stubbed — the
// enums still come from `src/types/tournament.ts`, never from this test.
function loadTsModule(relativePath, requireModule) {
  const source = fs.readFileSync(path.join(repoRoot, relativePath), 'utf8');
  const code = ts.transpileModule(source, {
…
  }).outputText;
  const loaded = { exports: {} };
  vm.runInNewContext(code, { … });
  return loaded.exports;
}

const tournamentTypes = loadTsModule('src/types/tournament.ts', (specifier) => {
  if (specifier === './category') return {};
  throw new Error(`Unexpected module: ${specifier}`);
});

// Values cross a realm boundary out of the VM, so collections are copied into
// this realm before any structural comparison.
const keysOf = (options) => Array.from(options, (option) => option.key);

const { MatchTypeDB, GenderRestriction } = tournamentTypes;

const quickFormats = loadTsModule(
  'src/app/organizer/tournaments/create/quickTournamentFormats.ts',
  (specifier) => {
    if (specifier === '@/types/tournament') return tournamentTypes;
    throw new Error(`Unexpected module: ${specifier}`);
  },
);

test('flexible formats are offered for racket sports and never preselected', () => {
  const flexibleKeys = Array.from(
    quickFormats.QUICK_FORMAT_OPTIONS.filter((option) => option.key.startsWith('OPEN_')),
    (option) => option.key,
  );

  assert.deepStrictEqual(flexibleKeys, ['OPEN_SINGLES', 'OPEN_DOUBLES']);
  assert.ok(quickFormats.DEFAULT_RACKET_FORMATS.includes('OPEN_SINGLES'));
  assert.ok(quickFormats.DEFAULT_RACKET_FORMATS.includes('OPEN_DOUBLES'));
  assert.ok(
    quickFormats.DEFAULT_FOOTBALL_FORMATS.every((key) => !key.startsWith('OPEN_')),
    'football must not offer flexible formats',
  );
  assert.deepStrictEqual(
    keysOf(quickFormats.DEFAULT_VISIBLE_RACKET_FORMAT_OPTIONS),
    ['MALE_DOUBLES', 'FEMALE_DOUBLES', 'MIXED_DOUBLES'],
    'the default quick-create cards must stay exactly the ones shown before flexible formats',
  );
});

test('a flexible division is created without any gender restriction', () => { … });

test('gender-restricted formats keep their gate', () => { … });

