const quickDefaults = () => {
  return {
    registrationStart: '',
    registrationEnd: '',
    startDate: '',
    endDate: '',
  };
};

export default function QuickTournamentCreate() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const user = useAuthStore((state) => state.user);
  const hasSystemAdmin = Boolean(user?.roles?.some((role) => role === 'ADMIN'));
  const hasOrganizerRole = Boolean(
    user?.roles?.some((role) => role === 'ORGANIZER' || role === 'ADMIN'),
  );
  const translate = useTranslations('OrganizerQuickCreate');
  const quickSchema = useMemo(() => buildQuickSchema(translate), [translate]);
  const getFormatLabel = (key: string) => {
    const option = QUICK_FORMAT_OPTIONS.find((item) => item.key === key);
    return option ? translate(option.labelKey) : key;
  };
  const getBracketLabel = (key: QuickValues['bracketType']) => {
    const option = BRACKET_OPTIONS.find((item) => item.id === key);
    return option ? translate(option.labelKey) : translate('bracketSingleLabel');
  };
  const parentId = searchParams.get('parentId') || undefined;
  const communityId = searchParams.get('communityId') || undefined;
  const [communityRoleResult, setCommunityRoleResult] = useState<{
    communityId: string;
    role: Community['myRole'] | null;
  } | null>(null);
  const communityRole = communityId && communityRoleResult && communityRoleResult.communityId === communityId
    ? communityRoleResult.role
    : null;
  const isCommunityRoleLoading = Boolean(communityId) && communityRoleResult?.communityId !== communityId;
  const canCreateTournament = communityId
    ? hasSystemAdmin || communityRole === 'OWNER' || communityRole === 'MODERATOR'
    : hasOrganizerRole;
  const scheduleDefaults = useMemo(() => quickDefaults(), []);
  const [categories, setCategories] = useState<Category[]>([]);
  const [feeConfig, setFeeConfig] = useState<{ allowEntryFees: boolean } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isUploadingMedia, setIsUploadingMedia] = useState(false);
  const [logoCropModalOpen, setLogoCropModalOpen] = useState(false);
  const [pendingLogoSrc, setPendingLogoSrc] = useState('');
  const { register, handleSubmit, setValue, control, formState: { errors } } = useForm<QuickValues>({
    resolver: zodResolver(quickSchema),
    defaultValues: {
      sport: 'pickleball', format: 'doubles',
      tournamentType: communityId ? 'CLUB' : 'PUBLIC',
      visibility: communityId ? 'PRIVATE' : 'PUBLIC',
…
    },
  });
…
  const [isFormatModalOpen, setIsFormatModalOpen] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [showAdvancedOptions, setShowAdvancedOptions] = useState(false);
  const [showCreateOptions, setShowCreateOptions] = useState(false);
  const [editingFormatId, setEditingFormatId] = useState<string | null>(null);
  const [formatDraft, setFormatDraft] = useState<QuickFormatConfig>({
    id: 'MALE_DOUBLES',
    key: 'MALE_DOUBLES',
      label: translate('formatMaleDoubles'),
    bracketType: 'single_elimination',
    maxParticipantsOverride: false,
    maxParticipants: null,
    eloEnabled: false,
    minElo: null,
    maxElo: null,
  });
  const [formatConfigs, setFormatConfigs] = useState<QuickFormatConfig[]>(() =>
    createDefaultFormatConfigs(DEFAULT_VISIBLE_RACKET_FORMAT_OPTIONS, translate),
  );
  const hasDoublesContent = sport !== 'football' && selectedFormats.some((formatId) => {
    const config = formatConfigs.find((item) => item.id === formatId || item.key === formatId);
    return (config?.key ?? formatId).includes('DOUBLES');
  });
  const draftHydratedRef = useRef(false);

  useEffect(() => {
    if (!isFormatModalOpen && !isAiModalOpen) return;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      if (isFormatModalOpen) setIsFormatModalOpen(false);
      if (isAiModalOpen) setIsAiModalOpen(false);
    };
    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [isAiModalOpen, isFormatModalOpen]);

  const draftKey = `sporto:tournament-quick-draft:${communityId || 'public'}`;

  useEffect(() => {
    if (typeof window === 'undefined' || draftHydratedRef.current) return;
    draftHydratedRef.current = true;
…
  }, [draftKey, setValue]);
…
}

